// Audit 2026-11-18 item 6: an owner's actions on a task the core engine owns, through Cloud's handler, against a fake Code that answers with fixtures copied from real Code
// answers (tests/fixtures/code-core-task-actions.json, generated by running Code's own routes; see its `_about`). Code's old workflow routes answer a core task 404 "That is not
// on the core engine on this install yet." to a person the core lets read the task; Cloud then uses the core's own route for the same act, as the same person:
//   - Retry reviews and Close: `POST /v1/app/sessions/{codeSession}/retry|close`; a task Code holds no session for gets fixed words, and nothing is done;
//   - plan approval: Code's `approve_plan` decision card, so Cloud's approval page, banner and Home card stop pointing at a page the core does not take;
//   - accepting a security finding: Code's refusal (its web page with a fresh step-up only) becomes fixed words, never Code's bare 403.
// Every action has its auth negatives: a member of the company without access to the task, and a person of another company.
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { CodeClient, LocalSessionStore, LocalWorkSessionStore, createCloudHandler, type CloudRequest, type CodeSession, type WorkSession } from "../../packages/cloud-server/src/index.js";
import { CORE_ACTION_WORDS } from "../../packages/cloud-server/src/core-task-actions.js";
import { codeSessionIdOf } from "../../packages/cloud-server/src/inbox-routes.js";
import { SessionResponseReaderSchema } from "../../packages/contracts/src/web.js";

type Obj = Record<string, unknown>;
interface Fixture {
  coreNotYet: { status: number; body: Obj };
  missingTask: { status: number; body: Obj };
  noSession: { status: number; body: Obj };
  sessionLevel: { status: number; body: Obj };
  securityRefusal: { status: number; body: Obj };
  securityStale: { status: number; body: Obj };
  reviewBlockedTask: Obj;
  planReviewTask: Obj;
  retry: { status: number; body: Obj };
  close: { status: number; body: Obj };
  decisions: Obj;
}
const FIXTURE = JSON.parse(readFileSync(new URL("../fixtures/code-core-task-actions.json", import.meta.url), "utf8")) as Fixture & { _about: string; taskId: string; sessionId: string };

const CODE = "https://code.example.test";
const ORIGIN = "https://cloud.example.test";
const ADA = "a".repeat(64);
const SAM = "b".repeat(64);
const EVE = "c".repeat(64);
const TASK = "6f9d0c1e-2b3a-4c5d-8e7f-001122334455";
const OTHER_TASK = "7a9d0c1e-2b3a-4c5d-8e7f-001122334466";
const CODE_SESSION = codeSessionIdOf(TASK);
const CLOUD_SESSION = "ses_aaaaaaaaaaaaaaaaaaaa";
const REQUEST_ID = "33333333-3333-4333-8333-333333333333";
const UPPER_REQUEST_ID = "ABCDEF12-3333-4333-8333-33333333ABCD";

/** A fixture with its task's ids made this test's (the generated fixture names the task and session Code made). */
const ours = <T>(value: T, taskId = TASK): T => JSON.parse(JSON.stringify(value).replaceAll(FIXTURE.taskId, taskId).replaceAll(FIXTURE.sessionId, codeSessionIdOf(taskId))) as T;
const json = (status: number, body: unknown) => new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json" } });

interface CodeCall { method: string; path: string; token: string | undefined; body: unknown }
type Engine = "core" | "legacy";
interface Options {
  engine?: Engine;
  task?: "review" | "plan";
  /** Who Code lets read the task (core: and act on its session). */
  session?: "present" | "absent" | "level" | "foreign";
  security?: "forbidden" | "stale";
  cards?: "this" | "other" | "off" | "not-plan" | "decided";
  retryAnswer?: Obj;
}

function setUp(options: Options = {}) {
  const engine = options.engine ?? "core";
  const calls: CodeCall[] = [];
  const task = () => ours(options.task === "plan" ? FIXTURE.planReviewTask : FIXTURE.reviewBlockedTask);
  const fetchImpl = (async (input: string | URL | Request, init?: RequestInit) => {
    const url = new URL(input instanceof Request ? input.url : input);
    const headers = (init?.headers ?? {}) as Record<string, string>;
    const token = headers.authorization?.replace(/^Bearer /u, "");
    const call: CodeCall = { method: init?.method ?? "GET", path: url.pathname, token, body: typeof init?.body === "string" ? JSON.parse(init.body) : undefined };
    calls.push(call);
    if (url.pathname === "/v1/auth/token") return json(400, { error: "invalid_grant" });
    // Eve is another company's: every task route answers as for a task that does not exist, and her session reads are missing sessions.
    if (token === "eve-token") return url.pathname.startsWith("/v1/app/sessions/") ? json(FIXTURE.noSession.status, FIXTURE.noSession.body) : url.pathname === "/v1/app/decisions" ? json(200, { cards: [] }) : json(FIXTURE.missingTask.status, ours(FIXTURE.missingTask.body));
    // Sam, a member without access to the task, is told the same as Eve.
    if (token === "sam-token" && options.session !== "level") return url.pathname.startsWith("/v1/app/sessions/") ? json(FIXTURE.noSession.status, FIXTURE.noSession.body) : url.pathname === "/v1/app/decisions" ? json(200, { cards: [] }) : json(FIXTURE.missingTask.status, ours(FIXTURE.missingTask.body));
    if (url.pathname === `/v1/dev/tasks/${TASK}` && call.method === "GET") return json(200, { task: task() });
    if (url.pathname === "/v1/app/decisions") {
      if (options.cards === "off") return json(404, { error: { code: "NOT_FOUND", message: "route not found" } });
      const view = ours(FIXTURE.decisions, options.cards === "other" ? OTHER_TASK : TASK) as { cards: Obj[] };
      // This task's card, but not a pending coding plan: another kind, or one already decided.
      if (options.cards === "not-plan") view.cards = view.cards.map((card) => ({ ...card, kind: "approve_requirements" }));
      if (options.cards === "decided") view.cards = view.cards.map((card) => ({ ...card, status: "approved" }));
      return json(200, view);
    }
    const legacy = [`/v1/dev/tasks/${TASK}/workflow/review`, `/v1/dev/tasks/${TASK}/close`, `/v1/dev/tasks/${TASK}/workflow/decision`];
    if (legacy.includes(url.pathname) && call.method === "POST") {
      if (engine === "core") return json(FIXTURE.coreNotYet.status, FIXTURE.coreNotYet.body);
      return json(200, url.pathname.endsWith("/close") ? { task: { ...task(), status: "CLOSED" }, closed: true } : { task: task() });
    }
    if (url.pathname === `/v1/dev/tasks/${TASK}/workflow/review-findings` && call.method === "POST") {
      if (options.security === "stale") return json(FIXTURE.securityStale.status, FIXTURE.securityStale.body);
      if (options.security === "forbidden") return json(FIXTURE.securityRefusal.status, FIXTURE.securityRefusal.body);
      return json(200, { task: task() });
    }
    if ((url.pathname === `/v1/app/sessions/${CODE_SESSION}/retry` || url.pathname === `/v1/app/sessions/${CODE_SESSION}/close`) && call.method === "POST") {
      if (options.session === "absent") return json(FIXTURE.noSession.status, FIXTURE.noSession.body);
      if (options.session === "level" || token === "sam-token") return json(FIXTURE.sessionLevel.status, FIXTURE.sessionLevel.body);
      if (options.session === "foreign") return json(200, ours(FIXTURE.retry.body, OTHER_TASK));
      if (url.pathname.endsWith("/retry")) return json(FIXTURE.retry.status, options.retryAnswer ?? ours(FIXTURE.retry.body));
      return json(FIXTURE.close.status, ours(FIXTURE.close.body));
    }
    return json(404, { error: { code: "NOT_FOUND", message: "route not found" } });
  }) as typeof fetch;
  const store = new LocalSessionStore(undefined, { environment: {} });
  const work = new LocalWorkSessionStore();
  const client = new CodeClient({ baseUrl: CODE, clientId: "rovara-cloud", clientSecret: "secret", redirectUri: "http://127.0.0.1:8787/callback", scopes: "projects:members", fetch: fetchImpl });
  const handler = createCloudHandler({
    client, store, work, origin: ORIGIN, org: { orgId: "acme", name: "Acme", plan: "test" },
    callbackPath: "/callback", secureCookies: true, log: () => undefined, now: () => new Date(Date.UTC(2026, 10, 18)),
  });
  const record: WorkSession = { sessionId: CLOUD_SESSION, taskId: TASK, project: "demo", startedBy: { developerId: ADA, name: "Ada" }, owner: { developerId: ADA, name: "Ada" }, createdAt: "2026-11-18T10:00:00.000Z", revision: 1 };
  const signIn = async (token: string, access: CodeSession["access"]) => {
    await work.put({ ...record });
    await store.create(`cookie-${token}`, { accessToken: token, refreshToken: `r-${token}`, csrf: "csrf", signedInAt: "2026-11-18T00:00:00.000Z", access });
    return { cookie: `rovara_cloud_session=cookie-${token}`, "x-rovara-csrf": "csrf", origin: ORIGIN };
  };
  const send = async (method: string, target: string, body: unknown, headers: Record<string, string>, form = false) => {
    const url = new URL(target, "http://127.0.0.1:8787");
    const request: CloudRequest = {
      method, path: url.pathname, query: url.searchParams, headers: form ? { ...headers, "content-type": "application/x-www-form-urlencoded" } : headers,
      ...(body === undefined ? {} : { body: typeof body === "string" ? body : JSON.stringify(body) }),
    };
    const answered = await handler(request);
    const text = answered!.body;
    let parsed: unknown = text;
    try { parsed = JSON.parse(text); } catch { /* a page */ }
    return { status: answered!.status, body: parsed, headers: answered!.headers ?? {} };
  };
  const ada = () => signIn("ada-token", { developerId: ADA, displayName: "Ada", administrator: false, projects: [{ name: "demo", access: "developer" }], notices: [] });
  const sam = () => signIn("sam-token", { developerId: SAM, displayName: "Sam", administrator: false, projects: [{ name: "demo", access: "developer" }], notices: [] });
  const eve = () => signIn("eve-token", { developerId: EVE, displayName: "Eve", administrator: false, projects: [], notices: [] });
  const route = () => calls.map((call) => `${call.method} ${call.path}`);
  const coreSessionCalls = () => calls.filter((call) => call.path.startsWith("/v1/app/sessions/"));
  return { send, calls, route, coreSessionCalls, ada, sam, eve };
}

const RETRY = `/v1/web/sessions/${CLOUD_SESSION}/retry`;
const CLOSE = `/v1/web/sessions/${CLOUD_SESSION}/close`;
const ACCEPT = `/v1/web/sessions/${CLOUD_SESSION}/accept-findings`;
const APPROVE = `/v1/app/approve/plan-${CLOUD_SESSION}`;

describe("the fixture is Code's own", () => {
  it("names where it came from, and the core's words Cloud keys on", () => {
    expect(FIXTURE._about).toMatch(/Generated by running Rovara Code/u);
    expect(FIXTURE.coreNotYet.body).toEqual({ error: { code: "NOT_FOUND", message: "That is not on the core engine on this install yet." } });
    expect(FIXTURE.securityRefusal).toEqual({ status: 403, body: { error: { code: "FORBIDDEN", message: "Accepting a security finding needs the Rovara web page with a fresh sign-in" } } });
    expect(codeSessionIdOf(FIXTURE.taskId)).toBe(FIXTURE.sessionId);
  });
});

describe("Retry reviews on a core task", () => {
  it("asks the old route first, then retries through the task's Code session as the person, and answers the session from the core's task", async () => {
    const w = setUp();
    const res = await w.send("POST", RETRY, { requestId: REQUEST_ID }, await w.ada());
    expect(res.status).toBe(200);
    expect(w.route()).toEqual([`GET /v1/dev/tasks/${TASK}`, `POST /v1/dev/tasks/${TASK}/workflow/review`, `POST /v1/app/sessions/${CODE_SESSION}/retry`]);
    expect(w.coreSessionCalls()).toEqual([{ method: "POST", path: `/v1/app/sessions/${CODE_SESSION}/retry`, token: "ada-token", body: { requestId: REQUEST_ID } }]);
    const session = SessionResponseReaderSchema.parse(res.body).session;
    expect(session.sessionId).toBe(CLOUD_SESSION);
    expect((session.body as { task: { taskId: string } }).task.taskId).toBe(TASK);
  });

  it("sends Code's session control a lower-case request id (it takes no other)", async () => {
    const w = setUp();
    expect((await w.send("POST", RETRY, { requestId: UPPER_REQUEST_ID }, await w.ada())).status).toBe(200);
    expect(w.coreSessionCalls()[0]!.body).toEqual({ requestId: UPPER_REQUEST_ID.toLowerCase() });
  });

  it("a task Code holds no session for: fixed words, and nothing else is asked", async () => {
    const w = setUp({ session: "absent" });
    const res = await w.send("POST", RETRY, { requestId: REQUEST_ID }, await w.ada());
    expect(res).toMatchObject({ status: 501, body: { error: { code: "NOT_ON_CODE_YET", message: CORE_ACTION_WORDS.retry } } });
    expect(JSON.stringify(res.body)).not.toContain("There is no such session");
    expect(w.calls).toHaveLength(3);
  });

  it("an answer for another task, or one that does not read, is refused in fixed words", async () => {
    for (const w of [setUp({ session: "foreign" }), setUp({ retryAnswer: { session: { body: { kind: "task" } } } })]) {
      const res = await w.send("POST", RETRY, { requestId: REQUEST_ID }, await w.ada());
      expect(res).toEqual(expect.objectContaining({ status: 502, body: { error: { code: "RUNTIME_UNAVAILABLE", message: CORE_ACTION_WORDS.unreadable } } }));
    }
  });

  it("a workflow task is retried on the old route and never reaches a Code session", async () => {
    const w = setUp({ engine: "legacy" });
    expect((await w.send("POST", RETRY, { requestId: REQUEST_ID }, await w.ada())).status).toBe(200);
    expect(w.coreSessionCalls()).toEqual([]);
  });

  it("auth: a member who is not the owner is refused before anything acts; Code's session-level refusal passes through; another company reads no task", async () => {
    const sam = setUp();
    const refused = await sam.send("POST", RETRY, { requestId: REQUEST_ID }, await sam.sam());
    expect(refused.status).toBe(404);
    expect(sam.coreSessionCalls()).toEqual([]);
    expect(sam.route()).toEqual([`GET /v1/dev/tasks/${TASK}`]);
    const level = setUp({ session: "level" });
    expect((await level.send("POST", RETRY, { requestId: REQUEST_ID }, await level.sam())).status).toBe(403);
    expect(level.coreSessionCalls()).toEqual([]);
    const owner = setUp({ session: "level" });
    const byCode = await owner.send("POST", RETRY, { requestId: REQUEST_ID }, await owner.ada());
    expect(byCode).toMatchObject({ status: FIXTURE.sessionLevel.status, body: FIXTURE.sessionLevel.body });
    const eve = setUp();
    expect((await eve.send("POST", RETRY, { requestId: REQUEST_ID }, await eve.eve())).status).toBe(404);
    expect(eve.coreSessionCalls()).toEqual([]);
  });
});

describe("Close on a core task", () => {
  it("asks the old route first, then closes through the task's Code session with the request id only", async () => {
    const w = setUp({ task: "plan" });
    const res = await w.send("POST", CLOSE, { requestId: REQUEST_ID, discardUnpublished: true }, await w.ada());
    expect(res.status).toBe(200);
    expect(res.body).toMatchObject({ closed: true, session: { sessionId: CLOUD_SESSION } });
    expect(w.route()).toEqual([`POST /v1/dev/tasks/${TASK}/close`, `GET /v1/dev/tasks/${TASK}`, `POST /v1/app/sessions/${CODE_SESSION}/close`]);
    expect(w.coreSessionCalls()).toEqual([{ method: "POST", path: `/v1/app/sessions/${CODE_SESSION}/close`, token: "ada-token", body: { requestId: REQUEST_ID } }]);
  });

  it("a task Code holds no session for: fixed words", async () => {
    const w = setUp({ task: "plan", session: "absent" });
    expect(await w.send("POST", CLOSE, { requestId: REQUEST_ID }, await w.ada())).toMatchObject({ status: 501, body: { error: { code: "NOT_ON_CODE_YET", message: CORE_ACTION_WORDS.close } } });
  });

  it("a workflow task is closed on the old route only", async () => {
    const w = setUp({ engine: "legacy", task: "plan" });
    expect((await w.send("POST", CLOSE, { requestId: REQUEST_ID }, await w.ada())).status).toBe(200);
    expect(w.coreSessionCalls()).toEqual([]);
  });

  it("auth: a member without access gets the missing task and no session is touched; a reader without the level gets Code's refusal; another company is refused", async () => {
    const sam = setUp({ task: "plan" });
    const refused = await sam.send("POST", CLOSE, { requestId: REQUEST_ID }, await sam.sam());
    expect(refused).toMatchObject({ status: FIXTURE.missingTask.status, body: ours(FIXTURE.missingTask.body) });
    expect(sam.coreSessionCalls()).toEqual([]);
    const level = setUp({ task: "plan", session: "level" });
    expect(await level.send("POST", CLOSE, { requestId: REQUEST_ID }, await level.sam())).toMatchObject({ status: FIXTURE.sessionLevel.status, body: FIXTURE.sessionLevel.body });
    const eve = setUp({ task: "plan" });
    expect((await eve.send("POST", CLOSE, { requestId: REQUEST_ID }, await eve.eve())).status).toBe(404);
    expect(eve.coreSessionCalls()).toEqual([]);
  });
});

describe("Accept findings that include a security finding", () => {
  it("the core never takes it from a hosted route: Cloud says so in fixed words, never Code's bare 403", async () => {
    const w = setUp({ security: "forbidden" });
    const res = await w.send("POST", ACCEPT, { requestId: REQUEST_ID, reason: "A test token only." }, await w.ada());
    expect(res).toMatchObject({ status: 409, body: { error: { code: "SECURITY_ACCEPT_NOT_HERE", message: CORE_ACTION_WORDS.securityNotHere } } });
    expect(JSON.stringify(res.body)).not.toContain("Rovara web page");
    // The findings Cloud sent included the security review's, as the page showed them.
    const sent = w.calls.find((call) => call.path.endsWith("/workflow/review-findings"))!.body as { resolutions: unknown[] };
    expect(sent.resolutions).toHaveLength(2);
  });

  it("a stale step-up on the old engine asks the person to confirm it's them again", async () => {
    const w = setUp({ security: "stale" });
    expect(await w.send("POST", ACCEPT, { requestId: REQUEST_ID, reason: "A test token only." }, await w.ada())).toMatchObject({ status: 403, body: { error: { code: "REAUTH_REQUIRED", message: CORE_ACTION_WORDS.stepUp } } });
  });

  it("auth: a member without access and another company are refused before any finding is sent", async () => {
    for (const who of ["sam", "eve"] as const) {
      const w = setUp({ security: "forbidden" });
      expect((await w.send("POST", ACCEPT, { requestId: REQUEST_ID, reason: "ok" }, await w[who]())).status).toBe(404);
      expect(w.calls.some((call) => call.path.endsWith("/workflow/review-findings"))).toBe(false);
    }
    // A reader of the task who is not its owner: Cloud refuses before Code is asked to act.
    const reader = setUp({ security: "forbidden", session: "level" });
    expect((await reader.send("POST", ACCEPT, { requestId: REQUEST_ID, reason: "ok" }, await reader.sam())).status).toBe(403);
    expect(reader.calls.some((call) => call.path.endsWith("/workflow/review-findings"))).toBe(false);
  });
});

describe("plan approval on a core task: the decision card, not Cloud's approval page", () => {
  it("the session shows no approval link when Code holds this task's plan card, and keeps it otherwise", async () => {
    const onCard = setUp({ task: "plan" });
    const session = SessionResponseReaderSchema.parse((await onCard.send("GET", `/v1/web/sessions/${CLOUD_SESSION}`, undefined, await onCard.ada())).body).session;
    expect(session.approvals).toEqual([]);
    for (const cards of ["other", "off", "not-plan", "decided"] as const) {
      const w = setUp({ task: "plan", cards });
      const view = SessionResponseReaderSchema.parse((await w.send("GET", `/v1/web/sessions/${CLOUD_SESSION}`, undefined, await w.ada())).body).session;
      expect(view.approvals.map((approval) => approval.confirmUrl)).toEqual([`${ORIGIN}${APPROVE}`]);
    }
  });

  it("someone who is not the owner never has Code's decision list read for them", async () => {
    const w = setUp({ task: "plan", session: "level" });
    expect((await w.send("GET", `/v1/web/sessions/${CLOUD_SESSION}`, undefined, await w.sam())).status).toBe(200);
    expect(w.calls.some((call) => call.path === "/v1/app/decisions")).toBe(false);
  });

  it("Home's plan card opens the session (where the card is) instead of the approval page", async () => {
    const w = setUp({ task: "plan" });
    const home = await w.send("GET", "/v1/web/home", undefined, await w.ada());
    expect(home.body).toMatchObject({ cards: [{ kind: "plan", buttons: [{ label: "Review plan", action: "open", href: `${ORIGIN}/s/${CLOUD_SESSION}`, method: "GET" }, { action: "open" }] }] });
    const legacy = setUp({ task: "plan", cards: "off" });
    const old = await legacy.send("GET", "/v1/web/home", undefined, await legacy.ada());
    expect(old.body).toMatchObject({ cards: [{ kind: "plan", buttons: [{ label: "Review plan", action: "confirm", href: `${ORIGIN}${APPROVE}` }, { action: "open" }] }] });
  });

  it("the approval page sends the owner to the card and never posts a decision to the old route", async () => {
    const w = setUp({ task: "plan" });
    const headers = await w.ada();
    const shown = await w.send("GET", APPROVE, undefined, headers);
    expect(shown.status).toBe(200);
    expect(String(shown.body)).toContain(`href="/s/${CLOUD_SESSION}"`);
    expect(String(shown.body)).not.toContain("<form");
    const posted = await w.send("POST", APPROVE, "csrf=csrf&decision=APPROVE&revision=1&digest=x", headers, true);
    expect(posted.status).toBe(200);
    expect(w.calls.some((call) => call.path.endsWith("/workflow/decision"))).toBe(false);
  });

  it("when the card was not listed but Code says the task is the core's, nothing is decided and the page points at the card", async () => {
    const w = setUp({ task: "plan", cards: "other" });
    const headers = await w.ada();
    const shown = await w.send("GET", APPROVE, undefined, headers);
    const revision = /name="revision" value="(\d+)"/u.exec(String(shown.body))![1]!;
    const digest = /name="digest" value="([a-f0-9]{64})"/u.exec(String(shown.body))![1]!;
    const posted = await w.send("POST", APPROVE, `csrf=csrf&decision=APPROVE&revision=${revision}&digest=${digest}`, headers, true);
    expect(posted.status).toBe(200);
    expect(String(posted.body)).toContain(CORE_ACTION_WORDS.planOnCard);
    expect(w.calls.filter((call) => call.path.endsWith("/workflow/decision"))).toHaveLength(1);
  });

  it("auth: a member without access and another company see no plan and read no cards", async () => {
    for (const who of ["sam", "eve"] as const) {
      const w = setUp({ task: "plan" });
      const res = await w.send("GET", APPROVE, undefined, await w[who]());
      expect(res.status).toBe(404);
      expect(w.calls.some((call) => call.path === "/v1/app/decisions")).toBe(false);
    }
  });
});
